@push('scripts')<script>function openSupplierModal(){document.getElementById('supplier-modal').classList.remove('hidden')}function closeSupplierModal(){document.getElementById('supplier-modal').classList.add('hidden')}function openEntriesModal(name,entries){document.getElementById('entries-title').textContent='ENTRADAS DEL PROVEEDOR: '+name;const b=document.getElementById('entries-body');b.innerHTML=entries.length?entries.map(e=>`<tr class="border-t"><td class="p-3">${e.fecha??''}</td><td class="p-3 font-mono">${e.referencia??'â€”'}</td><td class="p-3 text-right font-bold">$${Number(e.total).toFixed(2)}</td></tr>`).join(''):'<tr><td colspan="3" class="p-6 text-center text-slate-400">No hay entradas registradas.</td></tr>';document.getElementById('entries-modal').classList.remove('hidden')}function closeEntriesModal(){document.getElementById('entries-modal').classList.add('hidden')}</script>@endpush